    where b.level = v.level and lower(btrim(b.name)) = lower(btrim(v.name))
 )
on conflict (id) do nothing;

select level, count(*) as boundaries
  from public.admin_boundaries
 where source = 'UNMIL; OCHA ROWCA, via geoBoundaries gbOpen (William & Mary geoLab, www.geoboundaries.org); simplified geometry; CC BY 3.0 IGO'
 group by level
 order by level;
